"""Validate all stream records and generate a separate robustness table."""
from pathlib import Path
import csv,json,hashlib,sys,subprocess
import numpy as np
H=Path(__file__).resolve().parent;R=H.parents[1];O=H/'results';M=R/'docs/manuscript'
p=json.loads((H/'protocol.json').read_text());meta=json.loads((O/'metadata.json').read_text())
assert meta.get('completed') and meta['completed_seeds']==p['seeds']
for name,digest in meta['source_hashes'].items():assert hashlib.sha256((R/name).read_bytes()).hexdigest()==digest,name
summary=[];raw=[];checks=[];blocks=[]
for seed in p['seeds']:
 path=O/f'seed_{seed}.json';assert hashlib.sha256(path.read_bytes()).hexdigest()==meta['result_hashes'][path.name]
 r=json.loads(path.read_text());a=r['per_insertion_records'];assert len(a)==p['insertions'] and [x['step'] for x in a]==list(range(p['insertions']))
 assert r['seed']==seed and r['k_inserts']==p['insertions']
 assert [c['tag'] for c in r['correctness_checks']]==[f't={c}' for c in p['checkpoints']]
 for c in r['correctness_checks']:
  assert c['passed'] and c['n_inf_mismatch']==0 and c['max_abs_asymmetry']==0
  assert c['n_edges_checked']==c['n_edges_rebuilt'] and c['n_edges_checked']>0
  assert c['max_abs_delta_diff']<=p['tolerance'] and c['max_abs_w_diff_full_support']<=p['tolerance']
  checks.append(dict(seed=seed,**c))
 for x in a:
  assert x['n_active']==r['n_init']+x['step']+1
  assert all(np.isfinite(x[k]) and x[k]>=0 for k in ['total_ms','delta_ms','w_ms','bookkeeping_ms'])
  assert x['total_ms']+1e-6>=x['delta_ms']+x['w_ms']+x['bookkeeping_ms']
  raw.append(dict(seed=seed,**x))
 t=np.array([x['total_ms'] for x in a]);anchor=r['batch_anchors'][-1]['batch_total_s'];ratio=anchor*1000/t.mean()
 assert np.isclose(t.mean(),r['per_insertion_ms']['total_mean']) and np.isclose(ratio,r['speedup_end_to_end_stateful'])
 item=dict(seed=seed,n_init=r['n_init'],n_final=a[-1]['n_active'],steps=len(a),mean_ms=float(t.mean()),median_ms=float(np.median(t)),p90_ms=float(np.percentile(t,90)),max_ms=float(t.max()),batch_s=anchor,ratio=ratio,peak_rss_gb=r['peak_rss_gb'])
 summary.append(item)
 for start in range(0,len(a),200):blocks.append(dict(seed=seed,first_step=start+1,last_step=min(start+200,len(a)),mean_ms=float(t[start:start+200].mean()),max_ms=float(t[start:start+200].max())))
def csvout(name,rows):
 with (O/name).open('w') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
csvout('raw_results.csv',raw);csvout('summary.csv',summary);csvout('checks.csv',checks);csvout('blocks.csv',blocks)
with (O/'table.csv').open('w') as f:
 w=csv.writer(f);w.writerow(['Seed','Mean (ms)','Median (ms)','p90 (ms)','Max (ms)','Batch (s)','Batch/inc.'])
 for r in summary:w.writerow([r['seed']]+[f'{r[k]:.1f}' for k in ['mean_ms','median_ms','p90_ms','max_ms','batch_s','ratio']])
subprocess.run([sys.executable,str(R/'experiments/build_tables_from_csv.py'),'--csv',str(O/'table.csv'),'--output',str(M/'tables/tab_ogb_robustness.tex'),'--caption',r'Independent ogbn-arxiv streams with 1,000 insertions each. Latency statistics describe the steps within each stream; batch time is the final checkpoint rebuild with near-zero distance refinement.','--label','tab:ogb-robustness','--note',r'Each seed determines both the 80\% initial active set and the arrival order. Batch/inc. divides the final batch-anchor time by mean per-insertion latency, including bookkeeping. Initial construction and checkpoint validation are excluded from incremental latency; numerical refinement is included in batch timing. These runs are separate from the 200-step scaling point; no runs are pooled.','--note',r'Full maintained-state checks pass at steps 0, 500 and 1,000 for every seed (tolerance $10^{-9}$). Topology is laid out in advance and revealed through an active mask; timings exclude ingestion of unknown structure.'],check=True)
means=np.array([r['mean_ms'] for r in summary]);ratios=np.array([r['ratio'] for r in summary]);dmax=max(c['max_abs_delta_diff'] for c in checks);wmax=max(c['max_abs_w_diff_full_support'] for c in checks)
macro={'OgbRobustMean':f'{means.mean():.1f}','OgbRobustSD':f'{means.std():.1f}','OgbRobustRatio':f'{ratios.mean():.0f}','OgbRobustRatioSD':f'{ratios.std():.0f}','OgbRobustLow':f'{means.min():.1f}','OgbRobustHigh':f'{means.max():.1f}'}
worst=max(raw,key=lambda x:x['total_ms'])
macro.update({'OgbRobustWorstSec':f"{worst['total_ms']/1000:.2f}",'OgbRobustWorstTouch':str(worst['t_adj']),'OgbRobustWorstUpdates':str(worst['n_updates'])})
s='% Auto-generated by experiments/ogb_robustness/summarize.py — do not edit by hand\n% Source: experiments/ogb_robustness/results/raw_results.csv\n'
for k,v in macro.items():s+='\\newcommand{\\'+k+'}{'+v+'}\n'
(M/'tables/ogb_robustness_numbers.tex').write_text(s)
report='# OGB stream robustness — 2026-09-11\n\nAmended protocol v2, frozen before complete rerun after a documented Gram-cancellation incident: 3 seeds, 1000 sequential insertions per stream, checkpoint rebuilds at 0/500/1000. All 3000 records retained and all 9 full-state checks passed. This is variation across initial sets AND arrival order, not an isolated order-only test.\n\n| Seed | Mean ms | Median ms | p90 ms | Max ms | Final batch s | Ratio |\n|---|---:|---:|---:|---:|---:|---:|\n'
for r in summary:report+='| '+str(r['seed'])+' | '+' | '.join(f'{r[k]:.2f}' for k in ['mean_ms','median_ms','p90_ms','max_ms','batch_s','ratio'])+' |\n'
report+=f'\nAcross seeds: mean latency {means.mean():.3f} ± {means.std():.3f} ms; ratio {ratios.mean():.3f} ± {ratios.std():.3f} (population SD, n=3). This SD is between stream means, not per-insertion variability and not a confidence interval. Maximum radius discrepancy {dmax:.3e}; maximum weight discrepancy {wmax:.3e}. Peak RSS per seed (including initialization and reference rebuilds): '+', '.join(f"{r['peak_rss_gb']:.2f} GiB" for r in summary)+'.\n\n## Consecutive blocks of 200 insertions\n\n| Seed | Steps | Mean ms | Max ms |\n|---|---|---:|---:|\n'
for r in blocks:report+=f"| {r['seed']} | {r['first_step']}–{r['last_step']} | {r['mean_ms']:.3f} | {r['max_ms']:.3f} |\n"
report+='\nWorst recorded insertion (zero-based step index): `'+json.dumps(worst)+'`. Update count counts directed dictionary entries, not unique undirected edges. This high-latency event is retained.\n'
report+='\nOnly the early 1000 arrivals are evaluated. The active graph grows modestly; this does not replace the controlled scaling sweep or establish performance over the remaining full stream. Topology replay excludes unknown-edge ingestion. Seed 0 shares the earlier initial set and first 200 arrivals, but is an independently timed longer run. Do not pool the earlier latency with these measurements. Source/input hashes and environment are recorded in metadata.json; per-step CSV and per-seed JSON are retained.\n'
(R/'docs/ogb_robustness_results_2026-09-11.md').write_text(report)
print(report)

